import "server-only";import{and,desc,eq,inArray,sql}from"drizzle-orm";import{db}from"@/db";import{rankedChallengeRuns,rankedChallenges}from"@/db/schema";import{challengePhase}from"./policy";
export async function getChallengeDetail(challengeId:string,userId?:string){const[c]=await db.select().from(rankedChallenges).where(eq(rankedChallenges.id,challengeId)).limit(1);if(!c)return null;const result=await db.execute(sql`with ranked as (select r.id,r.user_id,r.total_score,rank() over(order by r.total_score desc)::int rank from ranked_challenge_runs r join profiles p on p.id=r.user_id where r.challenge_id=${challengeId} and r.status='COMPLETED' and p.ranking_visibility<>'HIDDEN') select x.id,x.user_id,x.total_score,x.rank,p.full_name,p.avatar_url,p.public_profile_id,p.ranking_visibility,count(*) over()::int participants from ranked x join profiles p on p.id=x.user_id order by x.rank,x.id limit 100`);const rows=(result.rows as Array<Record<string,unknown>>).map(x=>({runId:String(x.id),userId:String(x.user_id),score:Number(x.total_score),rank:Number(x.rank),participants:Number(x.participants),visibility:String(x.ranking_visibility),name:x.ranking_visibility==="PUBLIC"?String(x.full_name??"Learner"):null,avatarUrl:x.ranking_visibility==="PUBLIC"?x.avatar_url as string|null:null,publicProfileId:x.ranking_visibility==="PUBLIC"?String(x.public_profile_id):null}));const[own]=userId?await db.select().from(rankedChallengeRuns).where(and(eq(rankedChallengeRuns.challengeId,challengeId),eq(rankedChallengeRuns.userId,userId))).limit(1):[];const publicOwn=rows.find(x=>x.userId===userId);return{challenge:c,phase:challengePhase(c),leaderboard:rows,participants:rows[0]?.participants??0,own:own?{...own,rank:publicOwn?.rank??null,participants:rows[0]?.participants??0}:null};}
export async function getChallengeHistory(userId:string){return db.select({runId:rankedChallengeRuns.id,challengeId:rankedChallenges.id,type:rankedChallenges.type,titleEn:rankedChallenges.titleEn,titleVi:rankedChallenges.titleVi,total:rankedChallengeRuns.totalScore,listening:rankedChallengeRuns.listeningScore,reading:rankedChallengeRuns.readingScore,completedAt:rankedChallengeRuns.completedAt}).from(rankedChallengeRuns).innerJoin(rankedChallenges,eq(rankedChallenges.id,rankedChallengeRuns.challengeId)).where(and(eq(rankedChallengeRuns.userId,userId),eq(rankedChallengeRuns.status,"COMPLETED"))).orderBy(desc(rankedChallengeRuns.completedAt)).limit(30);}
export async function listDiscoverableChallenges(){return db.select().from(rankedChallenges).where(inArray(rankedChallenges.status,["PUBLISHED","CANCELLED"])).orderBy(desc(rankedChallenges.startsAt));}
